dat <- dat[order(dat$id, dat$t), ]
qaly <- tapply(seq_len(nrow(dat)), dat$id, function(i) {
  t <- dat$t[i]; q <- dat$q[i]
  sum(diff(t) * (head(q, -1) + tail(q, -1)) / 2)     # 梯形面积法
})

* Stata：为每个选择集追加 opt-out 行（alt == 3，属性全为 0）
local nset 4
forvalues s = 1/`nset' {
    set obs `=_N+1'
    replace choice_set = `s' if _n == _N
    replace alt = 3 if _n == _N
    foreach v in a b c d {
        replace `v' = 0 if _n == _N
    }
}

* Stata：评价类型选择示意（把结局类型写入 local 后运行）
local outcome "qaly"    // 可选：equivalent / natural / qaly / monetary
if "`outcome'" == "equivalent" {
    display "结局已证明等效 → 用 CMA（最小成本分析）"
}
else if "`outcome'" == "natural" {
    display "结局为自然单位（血压、生命年等）→ 用 CEA（成本-效果分析）"
}
else if "`outcome'" == "qaly" {
    display "结局为偏好加权指标（QALY/DALY）→ 用 CUA（成本-效用分析）"
}
else {
    display "结局已货币化或需跨领域比较 → 用 CBA（成本-效益分析）"
}

* Stata：贴现因子与 10 年年金贴现因子（r = 5%）
scalar r = 0.05
scalar df = 0
forvalues t = 1/10 {
    scalar df = df + 1 / (1 + r)^`t'
}
display "10 年、5% 的年金贴现因子 = " %9.4f df      // 7.7217

* 贴现后的增量成本与增量效果
scalar dC = (12000 - 8000) * df
scalar dE = (0.78 - 0.70) * df
display "贴现后 ΔC = " %9.2f dC                      // 30886.93 元
display "贴现后 ΔE = " %9.4f dE                      // 0.6177 QALY

* 贴现率敏感性（0–8%）
foreach rr in 0 0.03 0.05 0.08 {
    scalar df = 0
    forvalues t = 1/10 {
        scalar df = df + 1 / (1 + `rr')^`t'
    }
    display "r = " `rr' "：10 年年金贴现因子 = " %9.4f df
}

* Stata：ICER、净收益与四象限判断
scalar dC = 30886.9
scalar dE = 0.6177
scalar lambda = 100000
display "ICER = " %9.1f dC / dE                    // ≈ 50003 元/QALY
display "NB(λ=100000) = " %9.1f lambda * dE - dC   // ≈ 30887 元

if dC > 0 & dE > 0 {
    display "东北象限：更贵更有效 → 比较 ICER 与 λ"
    display cond(dC/dE < lambda, "ICER < λ → 具有成本-效果", "ICER ≥ λ → 不具有成本-效果")
}
else if dC < 0 & dE > 0 {
    display "东南象限：更便宜更有效 → 优势策略，直接推荐"
}
else if dC > 0 & dE < 0 {
    display "西北象限：更贵更差 → 劣势策略，拒绝"
}
else {
    display "西南象限：更便宜更差 → 权衡节省与效果损失"
}

# ---------- ICER 与 NMB ----------
dC   <- resB5["cost"] - resA5["cost"]
dE   <- resB5["qaly"] - resA5["qaly"]
c(dC = dC, dE = dE, ICER = dC / dE)   # 期望：dC≈726.90, dE≈0.3397, ICER≈2139.80

lam <- 100000                          # 阈值（1 倍人均 GDP）
NMB_A <- lam * resA5["qaly"] - resA5["cost"]
NMB_B <- lam * resB5["qaly"] - resB5["cost"]
c(NMB_A = NMB_A, NMB_B = NMB_B, dNMB = NMB_B - NMB_A)   # dNMB≈33243

# 象限与决策规则
if (dE > 0 & dC < 0) {
  "东南象限：占优（更便宜且更有效）→ 采纳"
} else if (dE < 0 & dC > 0) {
  "西北象限：被占优（更贵且更差）→ 拒绝"
} else if (dE > 0) {
  ifelse(dC/dE < lam, "东北象限：ICER < λ → 采纳", "东北象限：ICER ≥ λ → 拒绝")
} else {
  ifelse(dC/dE > lam,
         "西南象限：ICER > λ（节省的钱高于损失 QALY 的价值）→ 可采纳",
         "西南象限：ICER ≤ λ → 拒绝")
}
# 本例期望输出：dC>0 且 dE>0 → 东北象限，ICER≈2140 < 100000 → 采纳
